-- Transformer tests.
-- * "TypeEraser" cases are copied from Go internal/transformers/tstransforms/typeeraser_test.go.
-- * "tstransforms pipeline" expectations were generated by running the Go transformers
--   (Metadata, TypeEraser, RuntimeSyntax, LegacyDecorators) with the same stub resolver as below
--   (binder reference resolver + syntactic enum evaluation + a fixed type-reference serialization
--   table) and printing with the transform's EmitContext.
local ast = require("tslua.ast")
local core = require("tslua.core")
local parser = require("tslua.parser")
local binder = require("tslua.binder")
local printer = require("tslua.printer")
local evaluator = require("tslua.evaluator")
local transformers = require("tslua.transformers")
local tstransforms = require("tslua.transformers.tstransforms")
local inliners = require("tslua.transformers.inliners")

local function parseTypeScript(text, jsx)
    local fileName = jsx and "/main.tsx" or "/main.ts"
    return parser.ParseSourceFile({ fileName = fileName, path = fileName, externalModuleIndicatorOptions = { jsx = false, force = false } }, text, core.GetScriptKindFromFileName(fileName))
end

local function emit(emitContext, file)
    local p = printer.NewPrinter({ newLine = core.NewLineKind.LF }, {}, emitContext)
    local text = p:EmitSourceFile(file)
    if text:sub(-1) == "\n" then
        text = text:sub(1, -2)
    end
    return text
end

local function newStubResolver(ref)
    local sr = { ref = ref }
    for _, m in ipairs({ "GetReferencedExportContainer", "GetReferencedImportDeclaration", "GetReferencedValueDeclaration",
        "GetReferencedValueDeclarations", "GetElementAccessExpressionName", "GetReferencedMemberValueDeclaration" }) do
        sr[m] = function(self, ...) return self.ref[m](self.ref, ...) end
    end
    sr.eval = evaluator.NewEvaluator(function() return evaluator.NewResult(nil, false, false, false) end, ast.OuterExpressionKinds.OEKAll)
    function sr:GetEnumMemberValue(node)
        local init = node:Initializer()
        if init == nil then
            return evaluator.NewResult(nil, false, false, false)
        end
        return self.eval(init, node)
    end
    local known = { Foo = true, C = true, A = true, B = true }
    function sr:GetTypeReferenceSerializationKind(typeName, _)
        if ast.IsIdentifier(typeName) then
            local t = typeName:Text()
            if known[t] then
                return printer.TypeReferenceSerializationKindTypeWithConstructSignatureAndValue
            elseif t == "Array" then
                return printer.TypeReferenceSerializationKindArrayLikeType
            elseif t == "Promise" then
                return printer.TypeReferenceSerializationKindPromise
            end
        end
        return printer.TypeReferenceSerializationKindUnknown
    end
    return sr
end

