describe("transformers", function()
    describe("TypeEraser", function()
        for _, rec in ipairs(typeEraserCases) do
            it(rec[1], function()
                local file = parseTypeScript(rec[2], rec[4])
                assert.are.equal(0, #file:Diagnostics())
                local init = {}
                if rec[5] then
                    init.verbatimModuleSyntax = core.Tristate.TSTrue
                end
                local tx = tstransforms.NewTypeEraserTransformer({ compilerOptions = core.NewCompilerOptions(init), context = printer.NewEmitContext() })
                assert.are.equal(rec[3], emit(nil, tx:TransformSourceFile(file)))
            end)
        end
    end)

    describe("tstransforms pipeline", function()
        for i, rec in ipairs(pipelineCases) do
            it(string.format("#%d mode %d: %s", i, rec[2], rec[1]), function()
                local file = parseTypeScript(rec[1], false)
                binder.BindSourceFile(file)
                local init = {}
                if rec[2] == 1 then
                    init = {
                        experimentalDecorators = core.Tristate.TSTrue,
                        emitDecoratorMetadata = core.Tristate.TSTrue,
                        module = core.ModuleKind.System,
                        preserveConstEnums = core.Tristate.TSTrue,
                    }
                end
                local opts = core.NewCompilerOptions(init)
                local ctx = printer.NewEmitContext()
                local sr = newStubResolver(binder.NewReferenceResolver(opts, {}))
                local topts = { context = ctx, compilerOptions = opts, resolver = sr, emitResolver = sr }
                local factories = {}
                if rec[2] == 1 then
                    factories[#factories + 1] = tstransforms.NewMetadataTransformer
                end
                factories[#factories + 1] = tstransforms.NewTypeEraserTransformer
                factories[#factories + 1] = tstransforms.NewRuntimeSyntaxTransformer
                if rec[2] == 1 then
                    factories[#factories + 1] = tstransforms.NewLegacyDecoratorsTransformer
                end
                local chained = transformers.Chain(table.unpack(factories))(topts)
                assert.are.equal(rec[3], emit(ctx, chained:TransformSourceFile(file)))
            end)
        end
    end)

    describe("utilities", function()
        it("GetNonAssignmentOperatorForCompoundAssignment", function()
            local Kind = ast.Kind
            assert.are.equal(Kind.PlusToken, transformers.GetNonAssignmentOperatorForCompoundAssignment(Kind.PlusEqualsToken))
            assert.are.equal(Kind.QuestionQuestionToken, transformers.GetNonAssignmentOperatorForCompoundAssignment(Kind.QuestionQuestionEqualsToken))
            assert.are.equal(Kind.EqualsToken, transformers.GetNonAssignmentOperatorForCompoundAssignment(Kind.EqualsToken))
        end)

        it("FindSuperStatementIndexPath", function()
            local file = parseTypeScript("class C extends B { constructor() { a; try { b; super(); } finally {} } }", false)
            local ctor = file.statements.nodes[1].members.nodes[1]
            assert.are.same({ 1, 1 }, transformers.FindSuperStatementIndexPath(ctor.body.statements.nodes, 0))
            assert.is_nil(transformers.FindSuperStatementIndexPath(ctor.body.statements.nodes, 2))
        end)

        it("ExtractModifiers", function()
            local file = parseTypeScript("export declare abstract class C {}", false)
            local mods = transformers.ExtractModifiers(printer.NewEmitContext(), file.statements.nodes[1]:Modifiers(), ast.ModifierFlags.Export | ast.ModifierFlags.Abstract)
            assert.are.equal(2, #mods.nodes)
            assert.are.equal(ast.Kind.ExportKeyword, mods.nodes[1].kind)
            assert.are.equal(ast.Kind.AbstractKeyword, mods.nodes[2].kind)
        end)

        it("Chain", function()
            local single = function() return nil end
            assert.are.equal(single, transformers.Chain(single))
            assert.is_nil(transformers.Chain(single, single)({ context = printer.NewEmitContext() }))
        end)

        it("safeMultiLineComment", function()
            assert.are.equal(" a*_/b ", inliners.safeMultiLineComment("a*/b"))
            assert.are.equal(" x ", inliners.safeMultiLineComment("x"))
        end)
    end)
end)
